-- ISSUE-HYGIENE-6 (2026-10-26, pillar autonomy; follows hygiene-1 to -5): 9 open agent_issues closed with evidence that two independent measurements agreed on.
--
-- HOW THE LIST WAS MADE (read-only against live qnfo-audit, the repository and the fleet's hosts, 2026-10-26)
--   2026-10-26: the final run of the issue sweep (300 open agent_issues in 25 batches of up to 12, 66 agents: classifiers, then skeptics): 19 closes confirmed, 13 refuted and left open; 8 of the 19 were already closed by hygiene-4/5 and 2 more were closed meanwhile, the 9 below remain open and unclaimed (no work claim, no linked session, no live code task, re-read 2026-10-26T11:10Z)
--   Each issue was measured by one agent against its own definition of done, and every proposed close was then re-measured from scratch by skeptics told to refute it
--   and to default to refuted (two skeptics, different lenses, both had to confirm for a critical or high issue; one for the rest). Issues linked to a session, under a live
--   work claim or with a code task in flight were not touched. A close that rests on a duplicate names the OPEN successor that carries the work. Nothing is closed as wontfix
--   and no metric target was changed. The evidence of each issue is the text below, standalone and dated.
--
-- MECHANISM (as hygiene-1): issue_fold_ledger keeps the before-state of every row, the contracts leave the closing path, the close names its channel
--   (workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26-c), the evidence goes into issue_triage and the live trigger triage_close_sync_issue_upd closes the issue; no trigger is added.
--   Rows written: issue_fold_ledger 9, then at most 9 issue closes with their lifecycle rows. No DELETE, no DROP.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE issue_triage SET triage_state = (SELECT f.triage_state FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), close_evidence = (SELECT f.triage_close_evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), reopened_count = (SELECT f.triage_reopened_count FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), triaged_at = (SELECT f.triage_triaged_at FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-c' AND applied = 1); UPDATE agent_issues SET status = 'open', close_channel = (SELECT f.agent_close_channel FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-c' AND applied = 1) AND status = 'closed' AND close_channel = 'workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26-c'; UPDATE remediation_contracts SET status = (SELECT f.contract_status FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), last_verdict = (SELECT f.contract_last_verdict FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26-c' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE class IN (SELECT contract_class FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26-c' AND applied = 1 AND contract_class IS NOT NULL) AND last_verdict LIKE 'superseded:closure-superseded%'

-- 1. The ledger rows: each carries the before-state and the evidence
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26-c', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 100309 AS id, 'moot: stall premise false. Measured 2026-10-26 in qnfo-audit: transformation_levers id 4 anchor-repair status=landed since 2026-10-20 (tpPlan skips landed levers, no re-stall); program issue 2007 closed 2026-10-24, its probe returns ok now; orchestrator 0.29.0 live with repairAnchor/locateAnchor; 25 model repairs of a 0-match anchor in 14d (209 locator picks, 32 in 24h). Large-file no-anchor parks stay routed to their source issues.' AS ev, NULL AS succ UNION ALL SELECT 100404 AS id, 'moot: 2026-10-26: no live worker uses what this item deprecates (@cloudflare/shell, Think createExecuteTool, Think computer workspace). qnfo-agents (live 0.2.3, agents@0.30.1) extends Agent only; its lockfile holds no think/shell/computer. Only RETIRED qnfo-agent-ws, qnfo-artifact-agent and FOLDED qnfo-fleet-advisor name them; none is among the 36 account scripts. Catalog agents stays in_use (Agents SDK).' AS ev, NULL AS succ UNION ALL SELECT 100485 AS id, 'verified: Cloudflare API GET q08-mind/settings 2026-10-26T10:40Z compatibility_date 2026-10-01 (was 2026-09-01 through version 15; versions 16-26 all 2026-10-01); origin/main q08-mind/wrangler.toml declares 2026-10-01; worker_compat_state 09:31Z q08-mind days_behind 25 (gap rule is >=30), 36 workers, max 25, none at 30+; mind.q08.org routes and /health 200; no 2026-10-26 upgrade-compat gap; sibling 100486 closed with evidence; no work claim.' AS ev, NULL AS succ UNION ALL SELECT 100577 AS id, 'superseded by 100576 (Execute the seven fixes in 100140, owner-authorized): owner-session recorded task op-mvln7t9l2192 (2026-10-24 00:10:47: items 2-7 apply, item 1 after live-text recheck), note 50 ''approve all'' and card 135 done 00:11:33. Nothing is applied yet: 100576 stays open and carries the work; 100140 stays open, probe issue-100140 reads 3 on 2026-10-26.' AS ev, 100576 AS succ UNION ALL SELECT 1000034 AS id, 'verified: 2026-10-26 issues_unaccounted=1, hit 0 (thr 40). deleted_unrecorded 0 (raw sum 0, unclamped): issue_id_gap_ranges 100634..999998 never-allocated (0 issue/tombstone/lifecycle rows; drill sentinel 999999 moved seq) recorded 2026-10-24T14:52Z. metric_history 0 on 10-19..10-24, so not permanent. The 1 = closed_without_disposition 1000146 (born closed; reconcile_tick sees only dispositioned events): needs its own issue.' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26-c', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 1000148 AS id, 'superseded by 100419 (CLOSE-CHANNEL-REQUIRED-1): ct_im100419 (failed, MERGE-SCOPE wall, then read 404) targets migrations/2026-10-22-close-channel-required.sql, absent on origin/main and called the wrong target by 100419''s MEASURED CORRECTION; qnfo-pipeline-ops is RETIRED. 100419 stays open, unclaimed, with active contract issue-100419; live close sites write close_channel. 11 of 353 closes in 48h are NULL (2026-10-26).' AS ev, 100419 AS succ UNION ALL SELECT 1000166 AS id, 'verified: worker_compat_state 2026-10-26T09:31Z (qnfo-ops read of CF script settings): qnfo-workers live_date 2026-10-25, days_behind 1 (was 2026-08-10, 76, until 10-25T14:32Z); autopilot detector needs days_behind>=30, so no 10-26 upgrade-compat gap row; main wrangler.toml compatibility_date 2026-10-25; 14/14 deploys since 10-25 success, last 09:02Z, live date unchanged after it; no work claim on issue or file.' AS ev, NULL AS succ UNION ALL SELECT 1000263 AS id, 'verified: re-measured 2026-10-26T10:25Z. deployment_history has 2 success action=''deploy'' rows for qnfo-agents (ids 2439 09:11:52Z, 2442 09:17:59Z, qnfo-ops:cf_worker_deploy, http=200) plus 2 reconciled ''deployed'' rows; the deploy-unrecorded detector SELECT (v2 and v3 forms) returns no row for it; project_ledger W.qnfo-agents has deployed rows 1237, 1240; /health 200 v0.2.3; no claim on issue 1000263.' AS ev, NULL AS succ UNION ALL SELECT 1000264 AS id, 'moot: project-stale-deploy (active W.qnfo-agents, owner qnfo-agents, no success deploy in 30d) no longer holds on 2026-10-26: deployment_history ids 2439/2442 (09:11, 09:17, http=200) and fleet_deploys wrangler runs 40298747838/40300135753 ok=1 (sha a8259559 = main tip for qnfo-agents); project_deployment_state days_since_deploy=0; /health 200 version 0.2.3 = main VERSION.' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);

-- 2. Settle the contracts, name the channel, close through the triage row, mark the ledger
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:closure-superseded (ISSUE-HYGIENE-1)', last_attempt_at = datetime('now') WHERE class IN (SELECT f.contract_class FROM issue_fold_ledger f WHERE f.applied = 0 AND f.contract_class IS NOT NULL) AND status IN ('monitoring', 'escalated', 'active', 'holding', 'needs-machine-probe', 'probe-review-refused');
UPDATE agent_issues SET close_channel = 'workflow:ISSUE-HYGIENE-1 ' || (SELECT f.rule FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE status = 'open' AND id IN (SELECT issue_id FROM issue_fold_ledger WHERE applied = 0);
UPDATE issue_triage SET triage_state = 'closed', triaged_at = datetime('now'), close_evidence = (SELECT f.evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN agent_issues a ON a.id = f.issue_id WHERE f.applied = 0 AND a.status = 'open');
UPDATE agent_issues SET status = 'closed', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE status = 'open' AND id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN issue_triage t ON t.issue_id = f.issue_id WHERE f.applied = 0 AND t.triage_state = 'closed' AND t.close_evidence = f.evidence);
UPDATE issue_fold_ledger SET applied = 1, applied_at = datetime('now') WHERE applied = 0 AND (SELECT a.status FROM agent_issues a WHERE a.id = issue_fold_ledger.issue_id) <> 'open';
